import{_ as o,o as t,c as i,a2 as a}from"./chunks/framework.vLhlLNVn.js";const h=JSON.parse('{"title":"Pairing & Cryptography","description":"","frontmatter":{},"headers":[],"relativePath":"security/pairing-and-crypto.md","filePath":"security/pairing-and-crypto.md","lastUpdated":1795273079000}'),c={name:"security/pairing-and-crypto.md"};function d(n,e,r,s,l,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="pairing-cryptography" tabindex="-1">Pairing &amp; Cryptography <a class="header-anchor" href="#pairing-cryptography" aria-label="Permalink to &quot;Pairing &amp; Cryptography&quot;">​</a></h1><p>JetPack protects the local <code>127.0.0.1:9470</code> WebSocket channel with Out-of-Band (OOB) human authorization, mutual asymmetric authentication, ephemeral forward secrecy, and encrypted at-rest key storage.</p><h2 id="_1-out-of-band-pairing-jetpack-pair" tabindex="-1">1. Out-of-Band Pairing (<code>jetpack://pair</code>) <a class="header-anchor" href="#_1-out-of-band-pairing-jetpack-pair" aria-label="Permalink to &quot;1. Out-of-Band Pairing (`jetpack://pair`)&quot;">​</a></h2><p>Standard browser CORS is insufficient to protect a localhost daemon against DNS rebinding or rogue browser tabs. Every external origin must first pair out-of-band:</p><ol><li><strong>Identity Generation (<code>WasmClientIdentity</code>)</strong>: <ul><li>In the browser, <code>jetpack-wasm</code> generates a random <code>UUIDv4</code> <code>client_id</code> and two 32-byte seeds (<code>Ed25519</code> signing key + companion <code>X25519</code> static key) using <code>getrandom</code>, persisted in <code>window.localStorage</code> (<code>jetpack_client_id</code>, <code>jetpack_ed25519_seed</code>, <code>jetpack_x25519_seed</code>).</li></ul></li><li><strong>Pairing URI Construction</strong>: <ul><li>The client formats a deep link:<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jetpack://pair?client_id=&lt;uuid&gt;&amp;pubkey=&lt;urlsafe-base64&gt;&amp;origin=&lt;normalized-origin&gt;</span></span></code></pre></div></li><li><code>crates/jetpack-proto/src/pairing.rs</code> validates that <code>client_id</code> is an RFC 4122 UUID, <code>pubkey</code> decodes to 32 bytes (<code>Ed25519</code>) or 64 bytes (<code>Ed25519</code> + <code>X25519</code>), and <code>origin</code> is a valid <code>https://</code> origin or loopback <code>http://127.0.0.1</code> / <code>http://localhost</code>. Plain <code>http://</code> remote origins are rejected with <code>PairingUriError::InvalidOrigin</code>. <em>(Legacy <code>corenode://pair</code> URIs remain accepted for backwards compatibility.)</em></li></ul></li><li><strong>Single-Instance IPC Dispatch</strong>: <ul><li>When the OS launches <code>jetpack-daemon</code> via the custom URI handler (CLI arguments on Windows/Linux or <code>AppleEvent</code> on macOS), the secondary process pings <code>&lt;root&gt;/config/pairing.ipc</code> (<code>PING &lt;token&gt;</code>). If a primary daemon is running, it forwards the URI over local IPC and exits with status <code>0</code>.</li></ul></li><li><strong>Native OS Confirmation Dialog</strong>: <ul><li>On the main UI thread, <code>jetpack-daemon</code> displays a native OS modal dialog (<code>NSAlert</code> on macOS, <code>TaskDialog</code> on Windows, <code>GTK/Portal</code> on Linux via <code>rfd</code>) showing: <ul><li>Requesting web <code>origin</code></li><li><code>client_id</code> UUID</li><li>Deterministic <code>SHA-256</code> public key fingerprint (<code>SHA256:XX:YY:...</code>)</li></ul></li><li>Only clicking <strong>Yes / Allow</strong> persists the client in <code>paired_clients.db</code>. Dismissing or clicking <strong>No</strong> aborts without writing to disk.</li></ul></li></ol><h2 id="_2-encrypted-at-rest-storage-chacha20-poly1305-os-secret-vault" tabindex="-1">2. Encrypted At-Rest Storage (<code>ChaCha20-Poly1305</code> + OS Secret Vault) <a class="header-anchor" href="#_2-encrypted-at-rest-storage-chacha20-poly1305-os-secret-vault" aria-label="Permalink to &quot;2. Encrypted At-Rest Storage (`ChaCha20-Poly1305` + OS Secret Vault)&quot;">​</a></h2><p>Approved clients, authorized folder mounts (<code>authorized_volumes</code>), and daemon settings live in <code>&lt;root&gt;/config/paired_clients.db</code>, encrypted at rest as a <strong>pure-Rust <code>ChaCha20-Poly1305</code> (AEAD)</strong> container over serialized SQLite (<code>rusqlite</code> <code>bundled</code>, zero OpenSSL dependency).</p><ul><li><strong>Master Key &amp; AEAD Envelope</strong>: On first run, <code>OsKeyringStore</code> (<code>crates/jetpack-daemon/src/pairing.rs</code>) generates 32 cryptographically random bytes (<code>256-bit</code> key). Every write generates a fresh 96-bit CSPRNG nonce (<code>getrandom</code>), authenticates the <code>JPKDB01\\0</code> header + nonce as AAD, and atomically replaces <code>paired_clients.db</code>.</li><li><strong>OS Vault Storage (<code>keyring</code>)</strong>: The master key is never stored in plaintext config files. It is stored exclusively inside the host OS credential vault under service <code>io.jetpack.daemon</code> (with automatic migration from legacy <code>io.corenode.daemon</code>): <ul><li><strong>Windows</strong>: Windows Credential Manager / DPAPI</li><li><strong>macOS</strong>: macOS Keychain</li><li><strong>Linux</strong>: FreeDesktop Secret Service (<code>gnome-keyring</code> / <code>KWallet</code>)</li></ul></li><li>Attempting to inspect <code>paired_clients.db</code> with standard <code>sqlite3</code> without the vault key fails immediately with <code>Error: file is not a database</code>.</li></ul><h2 id="_3-authenticated-x25519-ed25519-session-handshake" tabindex="-1">3. Authenticated <code>X25519</code> + <code>Ed25519</code> Session Handshake <a class="header-anchor" href="#_3-authenticated-x25519-ed25519-session-handshake" aria-label="Permalink to &quot;3. Authenticated `X25519` + `Ed25519` Session Handshake&quot;">​</a></h2><p>Every WebSocket connection to <code>ws://127.0.0.1:9470</code> must pass two layers before any application data is processed:</p><ol><li><strong>HTTP Upgrade &amp; Private Network Access (PNA)</strong>: <ul><li>On <code>OPTIONS</code> preflight and <code>GET</code> WebSocket Upgrade, <code>ws_server.rs</code> normalizes the HTTP <code>Origin</code> header and verifies it against <code>paired_clients.db</code> (or the daemon&#39;s own Control Center origin <code>http://127.0.0.1:&lt;port&gt;</code>).</li><li>Unauthorized or missing origins receive <code>HTTP/1.1 403 Forbidden</code>.</li><li>Authorized origins receive <code>Access-Control-Allow-Origin: &lt;origin&gt;</code>, <code>Access-Control-Allow-Private-Network: true</code>, and <code>Vary: Origin</code>.</li></ul></li><li><strong>Post-Upgrade <code>ClientHello</code> / <code>ServerHello</code> (<code>crates/jetpack-proto/src/handshake.rs</code>)</strong>: <ul><li>Immediately after <code>101 Switching Protocols</code>, the client has <strong>5 seconds</strong> (<code>DEFAULT_HANDSHAKE_TIMEOUT</code>) to send a binary <code>ClientHello</code> envelope:<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Magic &quot;CNOD&quot; (4 B)] + [Version u16 LE (2 B)] + [MsgPack ClientHello]</span></span></code></pre></div><em>(Wire magic <code>&quot;CNOD&quot;</code> and transcript signing domain <code>b&quot;CORENODE-HANDSHAKE-V1&quot;</code> are preserved for protocol compatibility.)</em></li><li><code>ClientHello</code> contains <code>client_id</code>, <code>origin</code>, a fresh ephemeral <code>X25519</code> public key (<code>32 B</code>), a random <code>client_nonce</code> (<code>32 B</code>), and a 64-byte <code>Ed25519</code> signature over the transcript.</li><li><code>ServerHandshake</code> verifies: <ol><li><code>client_id</code> exists in <code>paired_clients.db</code>.</li><li><code>ClientHello.origin</code> matches <strong>both</strong> the stored <code>origin</code> in <code>paired_clients.db</code> and the HTTP Upgrade <code>Origin</code> header (preventing cross-client origin spoofing).</li><li>The <code>Ed25519</code> signature is valid under the stored public key.</li></ol></li><li>The daemon generates its own ephemeral <code>X25519</code> keypair and <code>server_nonce</code>, computes the ECDH shared secret, and derives three 256-bit secrets via <strong>HKDF-SHA256</strong> bound to the full handshake transcript: <ul><li><code>client_to_daemon_key</code> (<code>32 B</code>)</li><li><code>daemon_to_client_key</code> (<code>32 B</code>)</li><li><code>confirm_key</code> (<code>32 B</code>) + <code>session_id</code></li></ul></li><li>The daemon responds with <code>ServerHello</code> containing an <code>HMAC-SHA256</code> transcript confirmation tag (<code>confirm_key</code>), and both sides zeroize ephemeral private keys and raw shared secrets in memory (<code>zeroize::Zeroize</code>).</li></ul></li></ol><h2 id="_4-chacha20-poly1305-streaming-frames-replay-protection" tabindex="-1">4. <code>ChaCha20-Poly1305</code> Streaming Frames &amp; Replay Protection <a class="header-anchor" href="#_4-chacha20-poly1305-streaming-frames-replay-protection" aria-label="Permalink to &quot;4. `ChaCha20-Poly1305` Streaming Frames &amp; Replay Protection&quot;">​</a></h2><p>After <code>ServerHello</code>, all WebSocket messages are authenticated and encrypted with <code>ChaCha20-Poly1305</code> (RFC 8439) inside <code>SessionCipher</code> (<code>crates/jetpack-proto/src/framing.rs</code>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-------------------------------+----------------------------------------+------------------------+</span></span>\n<span class="line"><span>| seq: uint64 LE (8 B, AAD)     | Ciphertext of Plaintext HybridFrame    | Poly1305 Tag (16 B)    |</span></span>\n<span class="line"><span>+-------------------------------+----------------------------------------+------------------------+</span></span></code></pre></div><ul><li><strong>Directional 96-bit Nonces</strong>: <ul><li>Client -&gt; Daemon: <code>b&quot;C2D\\0&quot; || seq.to_le_bytes()</code> (<code>4 B + 8 B = 12 B</code>)</li><li>Daemon -&gt; Client: <code>b&quot;D2C\\0&quot; || seq.to_le_bytes()</code> (<code>4 B + 8 B = 12 B</code>)</li></ul></li><li><strong>Associated Data (AAD)</strong>: The 8-byte little-endian <code>seq</code> is passed as AAD to AEAD encryption/decryption.</li><li><strong>Strict Anti-Replay Enforcement</strong>: Both directions maintain independent <code>u64</code> sequence counters starting at <code>0</code>. Any frame arriving with an out-of-order, duplicated, or skipped <code>seq</code> is rejected with <code>ProtoError::InvalidSequenceNumber</code> without advancing the counter, and the WebSocket connection is closed immediately.</li><li><strong>Strict Binary-Only Policy</strong>: Sending any post-handshake WebSocket text/JSON frame (<code>Message::Text</code>) causes <code>jetpack-daemon</code> to immediately close the connection with <code>1003 Unsupported Data</code>.</li></ul>',15)])])}const u=o(c,[["render",d]]);export{h as __pageData,u as default};
